const W = 640, H = 220, L = 34, R = 8, T = 12, B = 26
const yMax = 250
const x = (i: number) => L + i * (W - L - R) / (points.length - 1)
const y = (v: number) => T + (1 - v / yMax) * (H - T - B)
const line = points.map(([, v], i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join('')
const area = `${line}L${x(points.length - 1)},${y(0)}L${x(0)},${y(0)}Z`
const minI = points.reduce((m, p, i) => p[1] < points[m][1] ? i : m, 0)
const maxI = points.reduce((m, p, i) => p[1] > points[m][1] ? i : m, 0)
const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
const hover = ref<number | null>(null)
function move(e: MouseEvent) {
  const svg = e.currentTarget as SVGSVGElement
  const px = (e.clientX - svg.getBoundingClientRect().left) / svg.getBoundingClientRect().width * W
  hover.value = Math.max(0, Math.min(points.length - 1, Math.round((px - L) / (W - L - R) * (points.length - 1))))
}
</script>

<template>
  <svg :viewBox="`0 0 ${W} ${H}`" class="grid-week" role="img" aria-label="Great Britain grid carbon intensity, one week, hourly: from 52 to 232 gCO2 per kWh" @mousemove="move" @mouseleave="hover = null">
    <g v-for="v in [0, 100, 200]" :key="v">
      <line :x1="L" :x2="W - R" :y1="y(v)" :y2="y(v)" class="gridline" />
      <text :x="L - 6" :y="y(v) + 3" class="axis" text-anchor="end">{{ v }}</text>
    </g>
    <g v-for="(d, i) in days" :key="d">
      <line v-if="i" :x1="x(i * 24)" :x2="x(i * 24)" :y1="T" :y2="y(0)" class="gridline" />
      <text :x="x(i * 24 + 12)" :y="H - 8" class="axis" text-anchor="middle">{{ d }}</text>
    </g>
    <path :d="area" class="area" />
    <path :d="line" class="line" />
    <circle :cx="x(minI)" :cy="y(points[minI][1])" r="4" class="dot" />
    <text :x="x(minI) + 8" :y="y(points[minI][1]) + 14" class="note">{{ points[minI][1] }} · windy</text>
    <circle :cx="x(maxI)" :cy="y(points[maxI][1])" r="4" class="dot" />
    <text :x="x(maxI)" :y="y(points[maxI][1]) - 8" class="note" text-anchor="middle">{{ points[maxI][1] }} · gas</text>
    <g v-if="hover !== null">
      <line :x1="x(hover)" :x2="x(hover)" :y1="T" :y2="y(0)" class="cross" />
      <circle :cx="x(hover)" :cy="y(points[hover][1])" r="4" class="dot" />
      <text :x="Math.min(x(hover) + 6, W - 120)" :y="T + 10" class="tip">{{ points[hover][0].replace('T', ' ') }}:00 · {{ points[hover][1] }} g/kWh</text>
    </g>
  </svg>
</template>

